import fs from 'fs';
import readline from 'readline';

const file = process.argv[2];
const rl = readline.createInterface({ input: fs.createReadStream(file) });

function truncate(s, n = 220) {
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

let prevTs = null;
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.ts || '';
  let gap = '';
  if (ts && prevTs) {
    const d = (new Date(ts) - new Date(prevTs)) / 1000;
    if (d > 30) gap = ` [+${d.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;

  const msg = e.message || e;
  const role = msg.role || e.type || '?';
  let out = [];
  if (Array.isArray(msg.content)) {
    for (const c of msg.content) {
      if (c.type === 'text') out.push(`TEXT: ${truncate(c.text)}`);
      else if (c.type === 'tool_use') out.push(`TOOL_USE ${c.name}: ${truncate(c.input)}`);
      else if (c.type === 'tool_result') {
        const content = Array.isArray(c.content) ? c.content.map(x => x.text || '').join(' ') : c.content;
        out.push(`TOOL_RESULT: ${truncate(content)}`);
      } else if (c.type === 'thinking') {
        out.push(`THINKING: ${truncate(c.thinking, 120)}`);
      }
    }
  } else if (typeof msg.content === 'string') {
    out.push(`TEXT: ${truncate(msg.content)}`);
  }
  if (out.length === 0) continue;
  console.log(`--${ts}${gap} [${role}]`);
  for (const o of out) console.log('  ' + o);
}

